1	package com.example.starter.blind;
2	
3	import com.fasterxml.jackson.databind.JsonNode;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.junit.jupiter.api.Test;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.boot.test.context.SpringBootTest;
8	import org.springframework.boot.test.web.client.TestRestTemplate;
9	import org.springframework.http.HttpEntity;
10	import org.springframework.http.HttpHeaders;
11	import org.springframework.http.HttpMethod;
12	import org.springframework.http.MediaType;
13	import org.springframework.http.ResponseEntity;
14	
15	import java.util.List;
16	
17	import static org.junit.jupiter.api.Assertions.assertEquals;
18	import static org.junit.jupiter.api.Assertions.assertFalse;
19	import static org.junit.jupiter.api.Assertions.assertNotNull;
20	
21	/**
22	 * 受控揭盲：申请、批准、结果查询的主流程与失败分支；
23	 * 关闭/退组不撤销已批准揭盲；处理代码仅在批准后对申请人可见。
24	 */
25	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
26	class UnblindFlowTest extends AbstractBlindIntegrationTest {
27	
28	    @Autowired
29	    private TestRestTemplate rest;
30	
31	    private final ObjectMapper mapper = new ObjectMapper();
32	
33	    private HttpHeaders headers(String actor, String role, String requestId) {
34	        HttpHeaders h = new HttpHeaders();
35	        h.set("X-Actor-Id", actor);
36	        h.set("X-Role", role);
37	        if (requestId != null) {
38	            h.set("X-Request-Id", requestId);
39	        }
40	        h.setContentType(MediaType.APPLICATION_JSON);
41	        return h;
42	    }
43	
44	    private ResponseEntity<String> exchange(String path, HttpMethod method,
45	                                            HttpHeaders headers, String body) {
46	        return rest.exchange(path, method, new HttpEntity<>(body, headers), String.class);
47	    }
48	
49	    private JsonNode json(ResponseEntity<String> response) throws Exception {
50	        assertNotNull(response.getBody());
51	        return mapper.readTree(response.getBody());
52	    }
53	
54	    private void setupExperimentWithParticipant(String expId, String requestIdPrefix) {
55	        assertEquals(201, exchange("/api/experiments/" + expId, HttpMethod.POST,
56	                headers("coord-1", "COORDINATOR", requestIdPrefix + "-create"),
57	                "{\"blockCount\":2}").getStatusCode().value());
58	        assertEquals(201, exchange(
59	                "/api/experiments/" + expId + "/participants/PA/allocations",
60	                HttpMethod.POST,
61	                headers("coord-1", "COORDINATOR", requestIdPrefix + "-alloc"), null)
62	                .getStatusCode().value());
63	    }
64	
65	    private String dbTreatment(long allocationId) {
66	        List<String> t = jdbc.queryForList(
67	                "SELECT s.treatment FROM allocation a JOIN seat s "
68	                        + "ON s.experiment_id = a.experiment_id "
69	                        + "AND s.block_no = a.block_no AND s.seat_no = a.seat_no "
70	                        + "WHERE a.id = ?", String.class, allocationId);
71	        return t.isEmpty() ? null : t.get(0);
72	    }
73	
74	    @Test
75	    void applyApproveAndResult_fullControlledUnblinding() throws Exception {
76	        setupExperimentWithParticipant("UB-1", "u1");
77	        long allocationId = jdbc.queryForObject(
78	                "SELECT id FROM allocation WHERE experiment_id = 'UB-1' AND participant_id = 'PA'",
79	                Long.class);
80	        String expectedTreatment = dbTreatment(allocationId);
81	        assertEquals("A", expectedTreatment, "第一区组第一席应为 A");
82	
83	        // 协调员申请揭盲
84	        ResponseEntity<String> apply = exchange(
85	                "/api/experiments/UB-1/participants/PA/unblind-requests", HttpMethod.POST,
86	                headers("coord-1", "COORDINATOR", "u1-apply"),
87	                "{\"reason\":\"合成测试需要核对处理代码\"}");
88	        assertEquals(201, apply.getStatusCode().value());
89	        JsonNode applyBody = json(apply);
90	        String ubId = applyBody.path("requestId").asText();
91	        assertEquals("PENDING", applyBody.path("status").asText());
92	        assertEquals("coord-1", applyBody.path("applicantActor").asText());
93	        assertFalse(applyBody.has("treatment"), "申请视图不得包含处理代码");
94	
95	        // 未批准：申请人查询结果 409
96	        ResponseEntity<String> pendingResult = exchange(
97	                "/api/unblind-requests/" + ubId + "/result", HttpMethod.GET,
98	                headers("coord-1", "COORDINATOR", null), null);
99	        assertEquals(409, pendingResult.getStatusCode().value());
100	
101	        // 协调员不能批准（仅 REVIEWER）
102	        ResponseEntity<String> coordinatorApprove = exchange(
103	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
104	                headers("coord-1", "COORDINATOR", "u1-approve-by-coord"), null);
105	        assertEquals(403, coordinatorApprove.getStatusCode().value());
106	
107	        // 申请人本人不能以 REVIEWER 身份批准（必须是另一名 REVIEWER）
108	        ResponseEntity<String> selfApprove = exchange(
109	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
110	                headers("coord-1", "REVIEWER", "u1-approve-self"), null);
111	        assertEquals(403, selfApprove.getStatusCode().value());
112	
113	        // 另一名 REVIEWER 批准
114	        clock.advance(10_000L);
115	        ResponseEntity<String> approved = exchange(
116	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
117	                headers("rev-2", "REVIEWER", "u1-approve"), null);
118	        assertEquals(200, approved.getStatusCode().value());
119	        JsonNode approvedBody = json(approved);
120	        assertEquals("APPROVED", approvedBody.path("status").asText());
121	        assertEquals("rev-2", approvedBody.path("reviewerActor").asText());
122	        assertFalse(approvedBody.has("treatment"), "批准响应仍不得直接返回处理代码");
